// ============================================================
// Neon Beats VR — Special Block Types
// Bombs (avoid!), slides (swipe across), and chains
// ============================================================

import {
  Group,
  Mesh,
  BoxGeometry,
  SphereGeometry,
  OctahedronGeometry,
  MeshBasicMaterial,
  LineSegments,
  EdgesGeometry,
  LineBasicMaterial,
  Color,
} from '@iwsdk/core';
import { LANE_COLORS } from './environment';

export type SpecialBlockType = 'bomb' | 'slide' | 'chain_start' | 'chain_end';

export interface SpecialBlockEvent {
  time: number;
  lane: number;
  type: SpecialBlockType;
  targetLane?: number; // for slides
}

export function createBombMesh(): Group {
  const group = new Group();

  // Red octahedron
  const bomb = new Mesh(
    new OctahedronGeometry(0.22, 0),
    new MeshBasicMaterial({ color: 0xff0000, transparent: true, opacity: 0.7 })
  );
  group.add(bomb);

  // Danger wireframe
  const edges = new LineSegments(
    new EdgesGeometry(new OctahedronGeometry(0.28, 0)),
    new LineBasicMaterial({ color: 0xff4444, transparent: true, opacity: 0.5 })
  );
  group.add(edges);

  // X marks
  for (const rot of [0, Math.PI / 2]) {
    const mark = new Mesh(
      new BoxGeometry(0.3, 0.04, 0.04),
      new MeshBasicMaterial({ color: 0xff6666, transparent: true, opacity: 0.8 })
    );
    mark.rotation.z = Math.PI / 4 + rot;
    group.add(mark);
  }

  return group;
}

export function createSlideMesh(fromLane: number, toLane: number): Group {
  const group = new Group();
  const fromColor = LANE_COLORS[fromLane % LANE_COLORS.length];
  const toColor = LANE_COLORS[toLane % LANE_COLORS.length];

  // Diamond shape
  const diamond = new Mesh(
    new BoxGeometry(0.3, 0.3, 0.1),
    new MeshBasicMaterial({ color: fromColor, transparent: true, opacity: 0.7 })
  );
  diamond.rotation.z = Math.PI / 4;
  group.add(diamond);

  // Arrow indicator
  const direction = toLane > fromLane ? 1 : -1;
  const arrow = new Mesh(
    new BoxGeometry(0.15, 0.04, 0.04),
    new MeshBasicMaterial({ color: toColor, transparent: true, opacity: 0.9 })
  );
  arrow.position.x = direction * 0.15;
  arrow.rotation.z = direction * -0.3;
  group.add(arrow);

  // Trail line showing direction
  const trail = new Mesh(
    new BoxGeometry(0.5 * Math.abs(toLane - fromLane), 0.02, 0.02),
    new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.3 })
  );
  trail.position.x = direction * 0.15 * Math.abs(toLane - fromLane);
  group.add(trail);

  return group;
}

// Generate special blocks for a song
export function generateSpecialBlocks(
  bpm: number,
  duration: number,
  difficulty: string,
  numLanes: number
): SpecialBlockEvent[] {
  const events: SpecialBlockEvent[] = [];
  const beatDur = 60 / bpm;

  // Bomb frequency
  const bombChance = difficulty === 'easy' ? 0.02 : difficulty === 'medium' ? 0.04 : difficulty === 'hard' ? 0.06 : 0.08;
  // Slide frequency
  const slideChance = difficulty === 'easy' ? 0 : difficulty === 'medium' ? 0.02 : difficulty === 'hard' ? 0.04 : 0.06;

  const totalBeats = Math.floor(duration / beatDur);
  for (let i = 8; i < totalBeats; i++) { // start after 8 beats
    const time = i * beatDur + 2; // 2s offset

    if (Math.random() < bombChance) {
      events.push({
        time,
        lane: Math.floor(Math.random() * numLanes),
        type: 'bomb',
      });
    }

    if (Math.random() < slideChance) {
      const fromLane = Math.floor(Math.random() * numLanes);
      let toLane: number;
      do {
        toLane = Math.floor(Math.random() * numLanes);
      } while (toLane === fromLane);
      events.push({
        time,
        lane: fromLane,
        type: 'slide',
        targetLane: toLane,
      });
    }
  }

  return events.sort((a, b) => a.time - b.time);
}

// ============================================================
// Neon Beats VR — Beat Blocks
// Block spawning, movement, hit detection
// ============================================================

import {
  Group,
  Mesh,
  BoxGeometry,
  MeshBasicMaterial,
  MeshStandardMaterial,
  LineSegments,
  EdgesGeometry,
  LineBasicMaterial,
  Color,
  Vector3,
  AdditiveBlending,
} from '@iwsdk/core';
import { LANE_COLORS, LANE_SPACING, LANE_LENGTH, HIT_ZONE_Z, SPAWN_Z } from './environment';
import type { BeatEvent } from './audio';
import { TIMING } from './game';

export interface ActiveBlock {
  mesh: Group;
  event: BeatEvent;
  lane: number;
  targetTime: number;
  speed: number;  // units per second
  alive: boolean;
  scored: boolean;
  holdProgress?: number;
}

const BLOCK_SIZE = 0.35;
const APPROACH_TIME = 2.0; // seconds for block to travel from spawn to hit zone

export function createBlockMesh(lane: number, type: 'tap' | 'hold' | 'double', holdDuration?: number): Group {
  const group = new Group();
  const color = LANE_COLORS[lane % LANE_COLORS.length];

  if (type === 'hold' && holdDuration) {
    // Hold block: elongated
    const length = holdDuration * (LANE_LENGTH / APPROACH_TIME);
    const body = new Mesh(
      new BoxGeometry(BLOCK_SIZE * 0.8, BLOCK_SIZE * 0.8, length),
      new MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.5,
      })
    );
    body.position.z = -length / 2;
    group.add(body);

    // Head block
    const head = new Mesh(
      new BoxGeometry(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE),
      new MeshBasicMaterial({ color, transparent: true, opacity: 0.9 })
    );
    group.add(head);

    // Wireframe on head
    const edges = new LineSegments(
      new EdgesGeometry(new BoxGeometry(BLOCK_SIZE * 1.05, BLOCK_SIZE * 1.05, BLOCK_SIZE * 1.05)),
      new LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.6 })
    );
    group.add(edges);
  } else {
    // Standard tap block
    const size = type === 'double' ? BLOCK_SIZE * 0.9 : BLOCK_SIZE;
    const block = new Mesh(
      new BoxGeometry(size, size, size),
      new MeshBasicMaterial({ color, transparent: true, opacity: 0.85 })
    );
    group.add(block);

    // Wireframe
    const edges = new LineSegments(
      new EdgesGeometry(new BoxGeometry(size * 1.08, size * 1.08, size * 1.08)),
      new LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 })
    );
    group.add(edges);

    // Inner glow core
    const core = new Mesh(
      new BoxGeometry(size * 0.4, size * 0.4, size * 0.4),
      new MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.6,
      })
    );
    group.add(core);

    // Arrow indicator for direction (visual flair)
    if (type === 'double') {
      // Double tap marker — two dots
      for (const ox of [-0.12, 0.12]) {
        const dot = new Mesh(
          new BoxGeometry(0.06, 0.06, size + 0.02),
          new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.8 })
        );
        dot.position.x = ox;
        group.add(dot);
      }
    }
  }

  return group;
}

export class BlockManager {
  private blocks: ActiveBlock[] = [];
  private container: Group;
  private numLanes: number;
  private speed: number;

  constructor(container: Group, numLanes: number) {
    this.container = container;
    this.numLanes = numLanes;
    this.speed = LANE_LENGTH / APPROACH_TIME;
  }

  spawnBlock(event: BeatEvent, songTime: number): ActiveBlock {
    const mesh = createBlockMesh(event.lane, event.type, event.holdDuration);
    const totalWidth = (this.numLanes - 1) * LANE_SPACING;
    const x = -totalWidth / 2 + event.lane * LANE_SPACING;
    const z = SPAWN_Z;
    mesh.position.set(x, 0.5, z);
    mesh.name = `block_${this.blocks.length}`;
    this.container.add(mesh);

    const block: ActiveBlock = {
      mesh,
      event,
      lane: event.lane,
      targetTime: event.time,
      speed: this.speed,
      alive: true,
      scored: false,
    };

    if (event.type === 'hold') {
      block.holdProgress = 0;
    }

    this.blocks.push(block);
    return block;
  }

  update(songTime: number, dt: number): ActiveBlock[] {
    const missedBlocks: ActiveBlock[] = [];

    for (const block of this.blocks) {
      if (!block.alive) continue;

      // Calculate position based on time until target
      const timeUntilHit = block.targetTime - songTime;
      const z = HIT_ZONE_Z + timeUntilHit * block.speed;
      block.mesh.position.z = z;

      // Rotate for visual flair
      block.mesh.rotation.y += dt * 1.5;
      block.mesh.rotation.x += dt * 0.5;

      // Pulse as it approaches
      const proximity = Math.max(0, 1 - Math.abs(timeUntilHit) / 0.5);
      const scale = 1 + proximity * 0.15;
      block.mesh.scale.setScalar(scale);

      // Check if missed (past the hit zone + grace period)
      if (songTime > block.targetTime + TIMING.miss && !block.scored) {
        block.scored = true;
        missedBlocks.push(block);
      }

      // Remove if way past
      if (songTime > block.targetTime + 1.0) {
        block.alive = false;
        this.container.remove(block.mesh);
      }
    }

    // Cleanup dead blocks
    this.blocks = this.blocks.filter(b => b.alive);

    return missedBlocks;
  }

  tryHitLane(lane: number, songTime: number): { block: ActiveBlock; timeDiff: number } | null {
    let bestBlock: ActiveBlock | null = null;
    let bestDiff = Infinity;

    for (const block of this.blocks) {
      if (!block.alive || block.scored || block.lane !== lane) continue;
      const diff = songTime - block.targetTime;
      const absDiff = Math.abs(diff);
      if (absDiff < TIMING.miss && absDiff < bestDiff) {
        bestDiff = absDiff;
        bestBlock = block;
      }
    }

    if (bestBlock) {
      bestBlock.scored = true;
      return { block: bestBlock, timeDiff: songTime - bestBlock.targetTime };
    }
    return null;
  }

  removeBlock(block: ActiveBlock) {
    block.alive = false;
    this.container.remove(block.mesh);
  }

  getUpcomingBlocks(songTime: number, lookAhead: number): BeatEvent[] {
    return this.blocks
      .filter(b => b.alive && !b.scored && b.targetTime > songTime && b.targetTime < songTime + lookAhead)
      .map(b => b.event);
  }

  clear() {
    for (const block of this.blocks) {
      this.container.remove(block.mesh);
    }
    this.blocks = [];
  }

  getActiveCount(): number {
    return this.blocks.filter(b => b.alive).length;
  }
}

// ============================================================
// Neon Beats VR — Main Entry Point (v0.3)
// Full game with modifiers, stats, visualizers, tunnel rings
// ============================================================

import {
  World,
  Color,
  AmbientLight,
  PointLight,
  Fog,
  Group,
  Vector3,
} from '@iwsdk/core';
import {
  createEnvironment,
  updateEnvironment,
  updateHitMarkerFlash,
  flashHitMarker,
  LANE_COLORS,
  HIT_ZONE_Z,
  LANE_SPACING,
} from './environment';
import { BlockManager, type ActiveBlock } from './blocks';
import {
  createInitialState,
  resetGameplay,
  getHitQuality,
  scoreHit,
  scoreMiss,
  getAccuracy,
  getGrade,
  saveHighScore,
  loadAllHighScores,
  type GameState,
} from './game';
import { getSong, getSongInfo, SONG_LIBRARY } from './songs';
import {
  initAudio,
  startMusic,
  stopMusic,
  getMusicTime,
  playHitSound,
  playMissSound,
  playComboSound,
  playCountdownBeep,
  playMenuSelect,
  type Song,
} from './audio';
import {
  ParticleSystem,
  HitFlashManager,
  ScreenShake,
  ComboPopupManager,
  BackgroundPulse,
  createLaneFlashEffect,
} from './effects';
import { SpeedLineManager, BeatPulseManager, StreakFire } from './trails';
import { WaveformVisualizer, TunnelRingManager } from './visualizer';
import {
  createHUD,
  updateHUD,
  showTimingFeedback,
  flashLaneKey,
  showHUD,
  hideHUD,
  type HUDElements,
} from './hud';
import {
  showTitleScreen,
  hideTitleScreen,
  showSongSelectScreen,
  hideSongSelectScreen,
  showCountdown,
  hideCountdown,
  showResultsScreen,
  hideResultsScreen,
  showPauseOverlay,
  hidePauseOverlay,
} from './ui';
import {
  createEndlessState,
  generateNextPhase,
  getEndlessDifficultyLabel,
  getEndlessPhaseColor,
  type EndlessState,
} from './endless';
import {
  createDefaultModifiers,
  getScoreMultiplier,
  loadStats,
  updateStatsAfterSong,
  type Modifiers,
  type PlayerStats,
} from './modifiers';
import {
  loadAchievements,
  checkAchievements,
  queueAchievementNotification,
  type Achievement,
  type AchievementContext,
} from './achievements';
import { calculateStars } from './rating';
import {
  showModifiersScreen,
  hideModifiersScreen,
  showStatsScreen,
  hideStatsScreen,
} from './screens';
import { TitleVisuals, FPSCounter, getComboColor } from './titlevisuals';
import { getHypeLevel, checkHypeLevelChange, resetHypeLevel } from './hype';
import { NeonTubeSystem, HolodeckHorizon } from './neontubes';
import { TimingMeter, ScreenFlash, getTimingLabel } from './feedback';

// ---- Globals ----
const container = document.getElementById('scene-container') as HTMLDivElement;
let world: World;
let state: GameState;
let hud: HUDElements;
let environment: Group;
let blockContainer: Group;
let effectsGroup: Group;
let blockManager: BlockManager;
let particles: ParticleSystem;
let hitFlash: HitFlashManager;
let screenShake: ScreenShake;
let comboPopups: ComboPopupManager;
let bgPulse: BackgroundPulse;
let speedLines: SpeedLineManager;
let beatPulse: BeatPulseManager;
let streakFire: StreakFire;
let waveformLeft: WaveformVisualizer;
let waveformRight: WaveformVisualizer;
let tunnelRings: TunnelRingManager;
let laneFlashes: { mesh: any; update: (dt: number) => boolean }[] = [];
let currentSong: Song | null = null;
let nextBeatIndex = 0;
let paused = false;
let pauseStartTime = 0;
let totalPausedTime = 0;
let lastFrameTime = 0;
let beatIntensity = 0;
let lastBeatTime = 0;
let endlessState: EndlessState;
let sceneLight1: PointLight;
let sceneLight2: PointLight;
let modifiers: Modifiers;
let playerStats: PlayerStats;
let songStartRealTime = 0;
let autoPlayIndex = 0;
let achievements: Achievement[];
let titleVisuals: TitleVisuals;
let fpsCounter: FPSCounter;
let neonTubes: NeonTubeSystem;
let holoHorizon: HolodeckHorizon;
let timingMeter: TimingMeter;
let screenFlash: ScreenFlash;

// Key mapping
const LANE_KEYS_4 = ['KeyD', 'KeyF', 'KeyJ', 'KeyK'];
let laneKeys = LANE_KEYS_4;
const keyState = new Map<string, boolean>();

// ---- Init ----

async function init() {
  let xrAvailable = false;
  try {
    if ((navigator as any).xr) {
      xrAvailable = await (navigator as any).xr.isSessionSupported('immersive-vr');
    }
  } catch {}

  world = await World.create(container, {
    xr: xrAvailable,
    render: {
      near: 0.01,
      far: 200,
      camera: {
        position: [0, 1.6, 0],
        lookAt: [0, 1.0, HIT_ZONE_Z],
      },
    },
    input: {
      canvasPointerEvents: !xrAvailable,
    },
    features: {
      grabbing: xrAvailable,
      locomotion: xrAvailable ? true : { browserControls: false },
      physics: false,
      spatialUI: false,
    },
  });

  // Scene setup
  world.scene.fog = new Fog(0x000008, 8, 35);
  world.scene.add(new AmbientLight(0x222244, 0.4));

  sceneLight1 = new PointLight(0x00ffff, 2.5, 20);
  sceneLight1.position.set(0, 5, HIT_ZONE_Z);
  world.scene.add(sceneLight1);

  sceneLight2 = new PointLight(0xff00ff, 2, 20);
  sceneLight2.position.set(0, 3, HIT_ZONE_Z - 12);
  world.scene.add(sceneLight2);

  // State
  state = createInitialState();
  state.highScores = loadAllHighScores();
  endlessState = createEndlessState();
  modifiers = createDefaultModifiers();
  playerStats = loadStats();
  achievements = loadAchievements();

  // Title visuals & FPS
  titleVisuals = new TitleVisuals();
  fpsCounter = new FPSCounter();

  // Neon decorations
  neonTubes = new NeonTubeSystem(effectsGroup);
  holoHorizon = new HolodeckHorizon(effectsGroup);
  timingMeter = new TimingMeter();
  screenFlash = new ScreenFlash();
  timingMeter.hide();

  // Environment
  environment = createEnvironment(state.numLanes);
  world.scene.add(environment);

  // Blocks
  blockContainer = new Group();
  blockContainer.name = 'blocks';
  world.scene.add(blockContainer);

  // Effects
  effectsGroup = new Group();
  effectsGroup.name = 'effects';
  world.scene.add(effectsGroup);

  particles = new ParticleSystem(effectsGroup);
  hitFlash = new HitFlashManager(effectsGroup);
  screenShake = new ScreenShake();
  comboPopups = new ComboPopupManager();
  bgPulse = new BackgroundPulse();
  speedLines = new SpeedLineManager(effectsGroup);
  beatPulse = new BeatPulseManager(effectsGroup);
  streakFire = new StreakFire(effectsGroup);
  tunnelRings = new TunnelRingManager(effectsGroup);

  // Waveform visualizers
  waveformLeft = new WaveformVisualizer(effectsGroup, 'left', 24);
  waveformRight = new WaveformVisualizer(effectsGroup, 'right', 24);

  // HUD
  hud = createHUD(state.numLanes);
  hideHUD(hud);

  // Block manager
  blockManager = new BlockManager(blockContainer, state.numLanes);
  laneKeys = LANE_KEYS_4;

  setupInput();
  showTitle();

  lastFrameTime = performance.now();
  world.onUpdate(gameLoop);
}

// ---- Input ----

function setupInput() {
  window.addEventListener('keydown', (e) => {
    if (keyState.get(e.code)) return;
    keyState.set(e.code, true);

    if (state.phase === 'playing' && !paused) {
      const laneIndex = laneKeys.indexOf(e.code);
      if (laneIndex >= 0 && !modifiers.autoPlay) {
        handleLaneHit(laneIndex);
      }
      if (e.code === 'Space' || e.code === 'Escape') {
        e.preventDefault();
        togglePause();
      }
    } else if (state.phase === 'playing' && paused) {
      if (e.code === 'Space' || e.code === 'Escape') {
        e.preventDefault();
        togglePause();
      }
    }
  });

  window.addEventListener('keyup', (e) => {
    keyState.set(e.code, false);
  });

  container.addEventListener('pointerdown', (e) => {
    if (state.phase !== 'playing' || paused || modifiers.autoPlay) return;
    const rect = container.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const lane = Math.floor(x * state.numLanes);
    if (lane >= 0 && lane < state.numLanes) {
      handleLaneHit(lane);
    }
  });
}

// ---- Phase Management ----

function showTitle() {
  state.phase = 'title';
  hideHUD(hud);
  hideSongSelectScreen();
  hideResultsScreen();
  hideModifiersScreen();
  hideStatsScreen();
  showTitleScreen(() => {
    titleVisuals.stop();
    hideTitleScreen();
    showSongSelect();
  });
  titleVisuals.start();
}

function showSongSelect() {
  state.phase = 'songSelect';
  state.endless = false;
  showSongSelectScreen(
    state.selectedSongIndex,
    state.highScores,
    (songId: string) => {
      if (songId === 'endless') {
        state.endless = true;
        state.songId = 'endless';
      } else if (songId === '_modifiers') {
        hideSongSelectScreen();
        showModifiersScreen(modifiers,
          (newMods) => { modifiers = newMods; hideModifiersScreen(); showSongSelect(); },
          () => { hideModifiersScreen(); showSongSelect(); }
        );
        return;
      } else if (songId === '_stats') {
        hideSongSelectScreen();
        showStatsScreen(playerStats, () => { hideStatsScreen(); showSongSelect(); });
        return;
      } else {
        state.songId = songId;
      }
      hideSongSelectScreen();
      startCountdown();
    },
    () => {
      hideSongSelectScreen();
      showTitle();
    }
  );
}

function startCountdown() {
  state.phase = 'countdown';
  resetGameplay(state);
  blockManager.clear();
  particles.clear();
  hitFlash.clear();
  comboPopups.clear();
  speedLines.clear();
  beatPulse.clear();
  streakFire.clear();
  tunnelRings.clear();
  laneFlashes = [];
  nextBeatIndex = 0;
  autoPlayIndex = 0;
  totalPausedTime = 0;
  resetHypeLevel();

  // Apply modifiers
  if (modifiers.noFail) state.maxHealth = 999;

  if (state.endless) {
    endlessState = createEndlessState(modifiers.halfSpeed ? 80 : 120);
    const { song } = generateNextPhase(endlessState, state.numLanes);
    currentSong = song;
    state.songDuration = 9999;
  } else {
    currentSong = getSong(state.songId, state.numLanes);
    state.songDuration = currentSong.duration;
    state.totalNotes = currentSong.beats.length;
  }

  // Mirror modifier
  if (modifiers.mirror && currentSong) {
    currentSong.beats = currentSong.beats.map(b => ({
      ...b,
      lane: state.numLanes - 1 - b.lane,
    }));
  }

  let count = 3;
  showCountdown(count);
  initAudio();
  playCountdownBeep(false);

  const countInterval = setInterval(() => {
    count--;
    hideCountdown();
    if (count > 0) {
      showCountdown(count);
      playCountdownBeep(false);
    } else if (count === 0) {
      showCountdown(0);
      playCountdownBeep(true);
    } else {
      clearInterval(countInterval);
      hideCountdown();
      startPlaying();
    }
  }, 800);
}

function startPlaying() {
  state.phase = 'playing';
  paused = false;
  showHUD(hud);
  timingMeter.show();
  speedLines.setActive(true);
  tunnelRings.setActive(true);
  songStartRealTime = performance.now();
  if (currentSong) startMusic(currentSong);
}

function finishSong() {
  state.phase = 'results';
  stopMusic();
  hideHUD(hud);
  timingMeter.hide();
  blockManager.clear();
  speedLines.setActive(false);
  speedLines.clear();
  tunnelRings.setActive(false);
  tunnelRings.clear();

  const playTime = (performance.now() - songStartRealTime) / 1000;
  const cleared = state.health > 0;

  // Update persistent stats
  playerStats = updateStatsAfterSong(
    playerStats, state.score, state.perfects, state.greats, state.goods,
    state.misses, state.maxCombo, playTime, state.songId, cleared
  );

  // Check achievements at song end
  const accuracy = getAccuracy(state);
  const grade = getGrade(accuracy);
  const achCtx: AchievementContext = {
    totalScore: playerStats.totalScore,
    bestCombo: playerStats.bestCombo,
    totalPerfects: playerStats.totalPerfects,
    totalSongsCleared: playerStats.totalSongsCleared,
    totalPlayTime: playerStats.totalPlayTime,
    currentCombo: state.maxCombo,
    currentScore: state.score,
    currentPerfects: state.perfects,
    accuracy,
    grade,
    songDifficulty: getSongInfo(state.songId)?.difficulty || '',
    endlessPhase: endlessState.phase,
  };
  const newAch = checkAchievements(achievements, achCtx);
  for (const a of newAch) queueAchievementNotification(a);

  if (state.endless) {
    const fakeSongInfo = {
      id: 'endless', name: 'ENDLESS MODE', artist: 'Infinite',
      bpm: endlessState.bpm,
      duration: Math.floor(endlessState.totalElapsed),
      difficulty: 'expert' as const,
      color: getEndlessPhaseColor(endlessState.phase),
      description: `Survived ${endlessState.phase} phases`,
    };
    const isNew = saveHighScore('endless', state.score);
    if (isNew) state.highScores.set('endless', state.score);
    showResultsScreen(state, fakeSongInfo, isNew,
      () => { hideResultsScreen(); startCountdown(); },
      () => { hideResultsScreen(); showSongSelect(); }
    );
  } else {
    const songInfo = getSongInfo(state.songId)!;
    const isNew = saveHighScore(state.songId, state.score);
    if (isNew) state.highScores.set(state.songId, state.score);
    showResultsScreen(state, songInfo, isNew,
      () => { hideResultsScreen(); startCountdown(); },
      () => { hideResultsScreen(); showSongSelect(); }
    );
  }
}

function togglePause() {
  if (state.phase !== 'playing') return;
  paused = !paused;
  if (paused) {
    pauseStartTime = performance.now();
    stopMusic();
    speedLines.setActive(false);
    tunnelRings.setActive(false);
    showPauseOverlay(
      () => togglePause(),
      () => {
        paused = false;
        hidePauseOverlay();
        stopMusic();
        blockManager.clear();
        hideHUD(hud);
        speedLines.setActive(false);
        tunnelRings.setActive(false);
        showSongSelect();
      }
    );
  } else {
    totalPausedTime += performance.now() - pauseStartTime;
    hidePauseOverlay();
    speedLines.setActive(true);
    tunnelRings.setActive(true);
    if (currentSong) startMusic(currentSong);
  }
}

// ---- Lane Hit Logic ----

function handleLaneHit(lane: number) {
  if (!currentSong) return;
  const songTime = getMusicTime();
  const result = blockManager.tryHitLane(lane, songTime);
  flashLaneKey(hud, lane, !!result);

  if (result) {
    const quality = getHitQuality(result.timeDiff);
    if (quality === 'miss') { handleMiss(result.block); return; }

    // Apply score multiplier from modifiers
    const origScore = state.score;
    scoreHit(state, quality);
    const gained = state.score - origScore;
    const modMult = getScoreMultiplier(modifiers);
    if (modMult !== 1) {
      state.score = origScore + Math.round(gained * modMult);
    }

    playHitSound(quality);
    showTimingFeedback(hud, quality);
    timingMeter.showTiming(result.timeDiff, quality);

    // Visuals (hype-aware)
    const hype = getHypeLevel(state.combo);
    const pos = result.block.mesh.position.clone();
    const color = LANE_COLORS[lane % LANE_COLORS.length];
    const basePCount = quality === 'perfect' ? 30 : quality === 'great' ? 18 : 10;
    const pCount = Math.round(basePCount * hype.particleMultiplier);
    particles.emit(pos, color, pCount, quality === 'perfect' ? 5 : 3);
    hitFlash.flash(pos, color, quality);
    flashHitMarker(environment, lane, quality === 'perfect' ? '#ffffff' : color.getStyle());

    const lf = createLaneFlashEffect(lane, state.numLanes, color);
    world.scene.add(lf.mesh);
    laneFlashes.push(lf);

    if (quality === 'perfect') beatPulse.pulse(color);
    if (state.combo > 10) {
      const totalWidth = (state.numLanes - 1) * LANE_SPACING;
      const x = -totalWidth / 2 + lane * LANE_SPACING;
      streakFire.emit(x, color);
    }

    if (state.combo > 0 && state.combo % 25 === 0) {
      playComboSound(state.combo);
      comboPopups.show(`${state.combo} COMBO!`, '#ffff00');
      screenShake.trigger(0.6);
      bgPulse.pulse('#ffff00', 0.8);
    } else if (state.combo > 0 && state.combo % 10 === 0) {
      comboPopups.show(`×${state.multiplier}`, '#ff00ff', 50, 45);
    }

    if (quality === 'perfect') {
      screenShake.trigger(0.12);
      bgPulse.pulse(color.getStyle(), 0.3);
    }

    blockManager.removeBlock(result.block);

    // Check hype level change
    const hypeChange = checkHypeLevelChange(state.combo);
    if (hypeChange.changed && hypeChange.direction === 'up' && hypeChange.level.name) {
      comboPopups.show(hypeChange.level.name, getComboColor(state.combo), 50, 28);
    }

    // Check achievements on combo milestones
    if (state.combo % 10 === 0) {
      const achCtx: AchievementContext = {
        totalScore: playerStats.totalScore,
        bestCombo: Math.max(playerStats.bestCombo, state.maxCombo),
        totalPerfects: playerStats.totalPerfects + state.perfects,
        totalSongsCleared: playerStats.totalSongsCleared,
        totalPlayTime: playerStats.totalPlayTime,
        currentCombo: state.combo,
        currentScore: state.score,
        currentPerfects: state.perfects,
        accuracy: getAccuracy(state),
        grade: '',
        songDifficulty: getSongInfo(state.songId)?.difficulty || '',
        endlessPhase: endlessState.phase,
      };
      const newAch = checkAchievements(achievements, achCtx);
      for (const a of newAch) queueAchievementNotification(a);
    }
  }
}

function handleMiss(block: ActiveBlock) {
  if (modifiers.noFail) {
    state.combo = 0;
    state.multiplier = 1;
    state.misses++;
  } else {
    scoreMiss(state);
  }
  playMissSound();
  showTimingFeedback(hud, 'miss');
  screenFlash.flash('#ff004440', 0.2, 150);
  screenShake.trigger(0.25);
  bgPulse.pulse('#ff0044', 0.4);
}

// ---- Game Loop ----

function gameLoop() {
  const now = performance.now();
  const dt = Math.min((now - lastFrameTime) / 1000, 0.1);
  lastFrameTime = now;

  if (state.phase !== 'playing' || paused) {
    updateEnvironment(environment, now / 1000, 0);
    particles.update(dt);
    hitFlash.update(dt);
    comboPopups.update(dt);
    speedLines.update(dt, 0.1);
    beatPulse.update(dt);
    streakFire.update(dt);
    tunnelRings.update(dt, 0);
    waveformLeft.update(dt, 0, now / 1000);
    waveformRight.update(dt, 0, now / 1000);
    neonTubes.update(now / 1000, 0, 1);
    holoHorizon.update(now / 1000, 0);
    fpsCounter.update();
    return;
  }

  const songTime = getMusicTime();
  state.songTime = songTime;

  // Beat detection
  if (currentSong) {
    const beatDuration = 60 / currentSong.bpm;
    const beatPhase = (songTime % beatDuration) / beatDuration;
    beatIntensity = Math.max(0, 1 - beatPhase * 3);

    const currentBeat = Math.floor(songTime / beatDuration);
    if (currentBeat !== lastBeatTime) {
      lastBeatTime = currentBeat;
      const pulseColor = LANE_COLORS[currentBeat % LANE_COLORS.length];
      sceneLight1.color.copy(pulseColor);
      sceneLight1.intensity = 4;
    }
  }

  sceneLight1.intensity = Math.max(2.5, sceneLight1.intensity * 0.95);

  // Spawn blocks
  if (currentSong) {
    const spawnAhead = 2.5;
    while (nextBeatIndex < currentSong.beats.length) {
      const beat = currentSong.beats[nextBeatIndex];
      if (beat.time - songTime > spawnAhead) break;
      blockManager.spawnBlock(beat, songTime);
      nextBeatIndex++;
    }

    // Endless: generate next phase
    if (state.endless && nextBeatIndex >= currentSong.beats.length - 5) {
      const { song } = generateNextPhase(endlessState, state.numLanes);
      currentSong.beats.push(...song.beats);
      comboPopups.show(`PHASE ${endlessState.phase}`, getEndlessPhaseColor(endlessState.phase), 50, 25);
      comboPopups.show(getEndlessDifficultyLabel(endlessState), '#ffffff', 50, 32);
    }
  }

  // Auto-play
  if (modifiers.autoPlay && currentSong) {
    while (autoPlayIndex < currentSong.beats.length) {
      const beat = currentSong.beats[autoPlayIndex];
      if (beat.time > songTime + 0.02) break;
      if (beat.time >= songTime - 0.02) {
        handleLaneHit(beat.lane);
      }
      autoPlayIndex++;
    }
  }

  // Update blocks (apply hidden/fadeIn modifiers)
  const missed = blockManager.update(songTime, dt);
  for (const block of missed) {
    if (!modifiers.autoPlay) handleMiss(block);
  }

  // Update visuals
  updateEnvironment(environment, now / 1000, beatIntensity);
  updateHitMarkerFlash(environment, state.numLanes);
  particles.update(dt);
  hitFlash.update(dt);
  screenShake.update(dt);
  comboPopups.update(dt);
  speedLines.update(dt, beatIntensity + (state.combo > 10 ? 0.3 : 0));
  beatPulse.update(dt);
  streakFire.update(dt);
  tunnelRings.update(dt, beatIntensity);
  waveformLeft.update(dt, beatIntensity, songTime);
  waveformRight.update(dt, beatIntensity, songTime);
  neonTubes.update(songTime, beatIntensity, state.multiplier);
  holoHorizon.update(songTime, beatIntensity);

  // Lane flashes
  for (let i = laneFlashes.length - 1; i >= 0; i--) {
    if (!laneFlashes[i].update(dt)) {
      world.scene.remove(laneFlashes[i].mesh);
      laneFlashes.splice(i, 1);
    }
  }

  // Screen shake
  if (!world.isInXR) {
    environment.position.x = screenShake.offset.x;
    environment.position.y = screenShake.offset.y;
    blockContainer.position.x = screenShake.offset.x;
    blockContainer.position.y = screenShake.offset.y;
  }

  // HUD
  const songName = state.endless ?
    `∞ Phase ${endlessState.phase} • ${endlessState.bpm} BPM` :
    getSongInfo(state.songId)?.name || '';
  updateHUD(hud, state.score, state.combo, state.multiplier, state.health,
    state.maxHealth, state.endless ? 1 : (currentSong ? songTime / currentSong.duration : 0), songName);

  // Game over / complete
  if (state.health <= 0 && !modifiers.noFail) { finishSong(); return; }
  if (!state.endless && currentSong && songTime >= currentSong.duration + 1) finishSong();
  fpsCounter.update();
}

// ---- Start ----
init().catch(console.error);
